<section id="contact" class="py-16 px-6 relative bg-section">
    <div class="max-w-7xl mx-auto relative z-10">
        <div class="text-center mb-8"><span class="reveal text-[9px] font-medium text-accent tracking-[0.25em] uppercase">Hubungi Kami</span><h2 class="reveal font-serif text-2xl md:text-4xl font-bold text-main mt-3 tracking-tight">Berkunjung <span class="text-grad">Yuk!</span></h2></div>
        <div class="flex flex-col md:flex-row gap-8">
            <div class="reveal-left flex-1 space-y-4">
                <div class="glass-card rounded-2xl p-4 flex items-start gap-3 border border-line hover-card"><div class="w-10 h-10 flex-shrink-0 rounded-xl bg-s-300/5 flex items-center justify-center text-accent"><span class="iconify text-base" data-icon="mdi:map-marker-outline"></span></div><div><h4 class="font-medium text-main text-xs mb-0.5">Lokasi</h4><p class="text-sub text-xs font-light">Jl. Saraso Koffiehaus, Padang, Sumatera Barat</p></div></div>
                <div class="glass-card rounded-2xl p-4 flex items-start gap-3 border border-line hover-card"><div class="w-10 h-10 flex-shrink-0 rounded-xl bg-s-300/5 flex items-center justify-center text-accent"><span class="iconify text-base" data-icon="mdi:phone-outline"></span></div><div><h4 class="font-medium text-main text-xs mb-0.5">Order & Call</h4><p class="text-sub text-xs font-light">Hubungi via WhatsApp untuk pemesanan</p></div></div>
                <div class="glass-card rounded-2xl p-4 flex items-start gap-3 border border-line hover-card"><div class="w-10 h-10 flex-shrink-0 rounded-xl bg-s-300/5 flex items-center justify-center text-accent"><span class="iconify text-base" data-icon="mdi:clock-outline"></span></div><div><h4 class="font-medium text-main text-xs mb-0.5">Jam Buka</h4><p class="text-sub text-xs font-light">Setiap hari, 07:00 – 00:00 WIB</p></div></div>
                <div class="flex gap-2 pt-1">
                    <a href="#" class="w-9 h-9 rounded-xl bg-s-300/5 border border-line flex items-center justify-center text-accent/50 hover:text-accent hover:bg-s-300/10 hover:border-s-300/20 transition-all"><span class="iconify" data-icon="mdi:instagram"></span></a>
                    <a href="#" class="w-9 h-9 rounded-xl bg-s-300/5 border border-line flex items-center justify-center text-accent/50 hover:text-accent hover:bg-s-300/10 hover:border-s-300/20 transition-all"><span class="iconify" data-icon="mdi:twitter"></span></a>
                    <a href="#" class="w-9 h-9 rounded-xl bg-s-300/5 border border-line flex items-center justify-center text-accent/50 hover:text-accent hover:bg-s-300/10 hover:border-s-300/20 transition-all"><span class="iconify" data-icon="mdi:whatsapp"></span></a>
                    <a href="https://maps.google.com" target="_blank" class="w-9 h-9 rounded-xl bg-s-300/5 border border-line flex items-center justify-center text-accent/50 hover:text-accent hover:bg-s-300/10 hover:border-s-300/20 transition-all"><span class="iconify" data-icon="mdi:google"></span></a>
                </div>
            </div>
            <div class="reveal-right flex-1">
                <form onsubmit="submitContact(event)" class="glass-card rounded-2xl p-5 space-y-3 border border-line">
                    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3"><div><label class="text-[9px] text-sub mb-1 block uppercase tracking-wider">Nama</label><input type="text" required placeholder="Nama Anda" class="w-full bg-input border border-line rounded-xl px-3 py-2.5 text-xs text-main placeholder:text-muted"></div><div><label class="text-[9px] text-sub mb-1 block uppercase tracking-wider">Email</label><input type="email" required placeholder="email@contoh.com" class="w-full bg-input border border-line rounded-xl px-3 py-2.5 text-xs text-main placeholder:text-muted"></div></div>
                    <div><label class="text-[9px] text-sub mb-1 block uppercase tracking-wider">Subjek</label><input type="text" required placeholder="Subjek pesan" class="w-full bg-input border border-line rounded-xl px-3 py-2.5 text-xs text-main placeholder:text-muted"></div>
                    <div><label class="text-[9px] text-sub mb-1 block uppercase tracking-wider">Pesan</label><textarea required rows="3" placeholder="Tulis pesan..." class="w-full bg-input border border-line rounded-xl px-3 py-2.5 text-xs text-main placeholder:text-muted resize-none"></textarea></div>
                    <button type="submit" class="w-full grad-warm text-dk-950 font-semibold text-xs py-3 rounded-xl hover:shadow-lg hover:shadow-s-300/20 transition-all duration-300">Kirim Pesan</button>
                </form>
            </div>
        </div>
    </div>
</section>
